import Foundation

/// The credits the About panel shows: the models and other credits
/// (`Acknowledgements.md`), then every linked crate's licence (`THIRD_PARTY_LICENSES.md`,
/// generated by `scripts/licenses.sh`). `scripts/build-app.sh` copies both into the bundle.
public enum Acknowledgements {
    public static let files = ["Acknowledgements.md", "THIRD_PARTY_LICENSES.md"]

    /// Both files from `bundle`'s resources, in order; a missing one is named instead.
    public static func text(in bundle: Bundle) -> String {
        files.map { name in
            bundle.resourceURL.flatMap { try? String(contentsOf: $0.appendingPathComponent(name), encoding: .utf8) }
                ?? "\(name) is missing from this build.\n"
        }.joined(separator: "\n\n")
    }
}
